<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin' })
const API_URL = 'http://localhost:8000'; const form = reactive({ name: '', slug: '' }); const saving = ref(false); const errorMessage = ref('')
watch(() => form.name, name => { if (!form.slug || form.slug === form.name.slice(0, -1)) form.slug = name.toLowerCase().trim().replace(/\s+/g, '-') })
const save = async () => { saving.value = true; try { await $fetch(`${API_URL}/categories`, { method: 'POST', body: form }); await navigateTo('/admin/categories') } catch { errorMessage.value = 'Unable to create category.' } finally { saving.value = false } }
</script>
<template><section><div class="mb-8"><p class="text-[10px] font-bold uppercase tracking-[0.24em] text-primary">Catalog</p><h1 class="mt-2 font-serif text-3xl font-bold tracking-tight text-ink sm:text-4xl">Add category</h1><p class="mt-2 text-sm text-gray-500">Create a category for your books.</p></div><p v-if="errorMessage" class="mb-5 rounded-xl bg-red-50 p-4 text-sm text-red-700">{{ errorMessage }}</p><form class="max-w-xl space-y-5 rounded-2xl border border-[#d9e7e2] bg-white p-6 shadow-sm" @submit.prevent="save"><label class="block"><span class="field-label">Name</span><input v-model="form.name" required class="field-input" /></label><label class="block"><span class="field-label">Slug</span><input v-model="form.slug" required class="field-input" /></label><div class="flex justify-end gap-3"><NuxtLink to="/admin/categories" class="rounded-xl border border-gray-200 px-5 py-3 text-sm font-semibold text-gray-600">Cancel</NuxtLink><button :disabled="saving" class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">{{ saving ? 'Saving...' : 'Save category' }}</button></div></form></section></template>
<style scoped>.field-label{display:block;margin-bottom:.5rem;font-size:.75rem;font-weight:700;color:#536461}.field-input{width:100%;border:1px solid #d7e1dd;border-radius:.75rem;padding:.75rem 1rem;outline:none}.field-input:focus{border-color:#0f766e;box-shadow:0 0 0 4px rgba(15,118,110,.1)}</style>
